    const [flow, inFlow] = await Promise.all([
      loadMetaFromIdb<boolean>(FLOW_SETTING_KEY),
      loadMetaFromIdb<boolean>("live-review-enabled"),
    ]);
    if (!active()) return;
    enabled = flow !== false && inFlow !== false;
    if (!enabled) {
      setFocus(false, "automatic focus switched off");
      setFlowAttribute(null);
    }
    publish();
  };

  /* ── Controller ─────────────────────────────────────────────── */

  const locate = (anchor: string): { from: number; to: number } | null => {
    const words = anchor.trim().split(/\s+/).slice(0, 14);
    if (!words.length || !words[0]) return null;
    const pattern = new RegExp(
      words.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("\\s+"),
    );
    let found: { from: number; to: number } | null = null;
    editor.state.doc.descendants((node, pos) => {
      if (found) return false;
      if (!node.isTextblock) return true;
      const match = pattern.exec(node.textContent);
      if (match) {
        // Positions inside a textblock: offset by 1 for the opening token,
        // and stay within the block if inline atoms shifted the offsets.
        const from = Math.min(pos + 1 + match.index, pos + node.nodeSize - 1);
        const long = anchor.trim().length > match[0].length + 20;
        const to = long
          ? pos + node.nodeSize - 1
          : Math.min(from + match[0].length, pos + node.nodeSize - 1);
        found = { from, to };
      }
      return false;
    });
    return found;
  };

  controller = ownedController = {
    dismiss(id) {
      if (!active()) return;
      const item = items.get(id);
      dismissed.add(id);
      if (item) {
        profile = recordItem(profile, item.kind, "dismissed", Date.now());
        profileDirty = true;
        logFlow("item", `Dismissed ${item.kind}: ${item.title}`);
      }
      publish();
    },
    engage(id) {
      if (!active()) return;
      const item = items.get(id);
      if (!item) return;
      profile = recordItem(profile, item.kind, "engaged", Date.now());
      profileDirty = true;
    },
    recall(id) {
      if (!active()) return;
      if (dismissed.delete(id)) publish();
    },
    anchorRects(item) {
      if (!active()) return [];
      const groups: DOMRect[][] = [];
      for (const anchor of item.anchors) {
        const range = locate(anchor);
        if (!range) continue;
        try {
          // One rect per line, so a highlight hugs the text instead of
          // boxing the whole paragraph.
          const start = editor.view.domAtPos(range.from);
          const end = editor.view.domAtPos(range.to);
          const dom = document.createRange();
          dom.setStart(start.node, start.offset);
          dom.setEnd(end.node, end.offset);
          const lines = Array.from(dom.getClientRects()).filter(
            (r) => r.width > 1 && r.height > 1,
          );
          if (lines.length) groups.push(lines);
        } catch {
          // Position outside the view (e.g. a collapsed page): skip it.
        }
      }
      return groups;
    },
    focusAnchor(item) {
      if (!active()) return;
      const range = item.anchors.map(locate).find(Boolean);
      if (!range) return;
      controller?.engage(item.id);
      editor.chain().focus().setTextSelection(range).scrollIntoView().run();
    },
    async draftAmendment(id) {
      if (!active()) return null;
      const item = items.get(id);
      if (!item?.data?.field) return null;
      try {
        const [{ loadAiSettingsFromIdb }, ai] = await Promise.all([
          import("../../../utils/idb"),
          import("../../../utils/ai-client"),
        ]);
        if (!active()) return null;
        const settings = await loadAiSettingsFromIdb();
        if (!active()) return null;
        if (!settings || !ai.hasConfiguredAiProvider(settings)) return null;
        const proposal = await ai.runClientDossierAmend(
          {
            field: item.data.field as DossierField,
            label: DOSSIER_FIELD_LABELS[item.data.field as DossierField],
            current: item.data.current,
            excerpt: item.data.excerpt,
            dossier: stack ? contextForModels(stack).text : "",
          },
          settings,
        );
        return active() ? proposal : null;
      } catch (error) {
        if (!active()) return null;
        logFlow("error", "Drafting an amendment failed", {
          error: String(error),
        });
        return null;
      }
    },
    async fileAmendment(id, text) {
      if (!active()) return "This folio has closed.";
      const item = items.get(id);
      const field = item?.data?.field as DossierField | undefined;
      const value = text.trim();
      if (!item || !field || !value) return "Write the new wording first.";
      try {
        const { loadProjectBriefForFolio, saveProjectBriefForFolio } =
          await import("../../../utils/anti-tabula-rasa");
        if (!active()) return "This folio has closed.";
        const current = (await loadProjectBriefForFolio(folioId)) ?? brief;
        if (!active()) return "This folio has closed.";
        if (!current) return "This folio has no dossier to amend yet.";
        const next: ProjectBrief = {
          ...current,
          answers: { ...current.answers, [field]: value },
          updatedAt: Date.now(),
        };
        await saveProjectBriefForFolio(folioId, next, {
          source: "amendment",
          reason: `The draft moved away from “${item.data?.current ?? ""}”.`,
        });
        if (!active()) return null;
        brief = next;
        items.delete(id);
        dismissed.add(id);
        driftLows[field] = 0;
        profile = recordItem(profile, "amendment", "engaged", Date.now());
        profileDirty = true;
        await refreshContext();
        if (!active()) return null;
        window.dispatchEvent(
          new CustomEvent(DOSSIER_AMENDED_EVENT, {
            detail: { folioId, brief: next },
          }),
        );
        logFlow("context", `Filed an amendment to ${field}`, { to: value });
        publish();
        return null;
      } catch (error) {
        return error instanceof Error
          ? error.message
          : "The dossier could not be amended.";
      }
    },
    release,
    items() {
      if (!active()) return [];
      return [...items.values()].filter((item) => !dismissed.has(item.id));
    },
    cursorTop() {
      if (!active()) return null;
      try {
        return editor.view.coordsAtPos(editor.state.selection.head).top;
      } catch {
        return null;
      }
    },
  };

  /* ── Wiring ─────────────────────────────────────────────────── */

  const onHouse = () => void refreshContext().then(() => publish());
  const onComments = () => void loadComments();
  let notesTimer: ReturnType<typeof setTimeout> | undefined;
  const onNotes = () => {
    if (!active()) return;
    clearTimeout(notesTimer);
    notesTimer = setTimeout(scanPersonaNotes, 60);
  };
  const onSourcesEvent = (event: Event) => void onSources(event);
  const onAmended = (event: Event) => {
    if (!active()) return;
    const d = (event as CustomEvent<{ folioId?: string; brief?: ProjectBrief }>)
      .detail;
    if (d?.folioId === folioId && d.brief) brief = d.brief;
  };

  editor.on("transaction", onTransaction);
  const interval = setInterval(tick, TICK_MS);
  window.addEventListener("twyne:zen-mode", onZen);
  window.addEventListener(FLOW_SETTING_EVENT, settings);
  window.addEventListener("twyne:live-review-setting", settings);
  window.addEventListener("twyne:user-comments-changed", onComments);
  window.addEventListener("twyne:persona-notes", onNotes);
  window.addEventListener("twyne:clear-persona-notes", onNotes);
  window.addEventListener("twyne:persona-reply-stream", onReplyStream);
  window.addEventListener("twyne:persona-replying", onReplying);
  window.addEventListener("twyne:persona-reply-thread", onReplyThread);
  window.addEventListener("twyne:background-sources", onSourcesEvent);
  window.addEventListener(HOUSE_CHANGED_EVENT, onHouse);
  window.addEventListener(DOSSIER_AMENDED_EVENT, onAmended);
  window.addEventListener("pointermove", onPointerMove, { passive: true });
  window.addEventListener("keydown", onKeyDown);

  void (async () => {
    const savedProfile = await loadMetaFromIdb<FlowProfile>(PROFILE_KEY);
    if (!active()) return;
    profile = normalizeProfile(savedProfile);
    await refreshContext();
    if (!active()) return;
    await settings();
    if (!active()) return;
    await loadComments();
    if (!active()) return;
    scanPersonaNotes();
  })();

  return () => {
    if (stopped) return;
    const ownsSnapshot = controller === ownedController;
    stopped = true;
    clearInterval(interval);
    clearTimeout(reachTimer);
    clearTimeout(notesTimer);
    if (ownsSnapshot && profileDirty) saveProfile();
    if (ownsSnapshot) {
      if (autoFocus) setFocus(false, "the folio closed");
      setFlowAttribute(null);
    }
    editor.off("transaction", onTransaction);
    window.removeEventListener("twyne:zen-mode", onZen);
    window.removeEventListener(FLOW_SETTING_EVENT, settings);
    window.removeEventListener("twyne:live-review-setting", settings);
    window.removeEventListener("twyne:user-comments-changed", onComments);
    window.removeEventListener("twyne:persona-notes", onNotes);
    window.removeEventListener("twyne:clear-persona-notes", onNotes);
    window.removeEventListener("twyne:persona-reply-stream", onReplyStream);
    window.removeEventListener("twyne:persona-replying", onReplying);
    window.removeEventListener("twyne:persona-reply-thread", onReplyThread);
    window.removeEventListener("twyne:background-sources", onSourcesEvent);
    window.removeEventListener(HOUSE_CHANGED_EVENT, onHouse);
    window.removeEventListener(DOSSIER_AMENDED_EVENT, onAmended);
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("keydown", onKeyDown);
    if (!ownsSnapshot) return;
    controller = null;
    snapshot = {
      ...snapshot,
      enabled: false,
      visible: [],
      held: 0,
      heldKinds: {},
      autoFocus: false,
    };
    window.dispatchEvent(
      new CustomEvent<FlowSnapshot>(FLOW_EVENT, { detail: snapshot }),
    );
  };
}

const round = (n: number) => Math.round(n * 100) / 100;
import { afterAll, afterEach, beforeAll, expect, mock, test } from "bun:test";
import type { Editor } from "@tiptap/core";
import type { ConvexClient } from "convex/browser";
import { Schema } from "@tiptap/pm/model";
import { EditorState, TextSelection } from "@tiptap/pm/state";
// @ts-expect-error jsdom is intentionally untyped in this project's test harness.
import { JSDOM } from "jsdom";
import { emptyHouseState } from "../../../utils/house-model";
import { lockBrowserGlobalsForTestFile } from "../../../utils/test-browser-globals-lock";

const releaseGlobals = await lockBrowserGlobalsForTestFile();
const originals = new Map(
  ["window", "document", "CustomEvent", "setInterval", "clearInterval"].map(
    (name) => [name, Object.getOwnPropertyDescriptor(globalThis, name)],
  ),
);
const ticks = new Map<number, () => void>();
let nextInterval = 0;
let judgementCalls = 0;
let coverCalls = 0;
type Judgement = {
  ok: boolean;
  answers: Record<string, { type: string; choice?: string; noul?: number }>;
};
const answers: Judgement = {
  ok: true,
  answers: {
    medium0: { type: "choice", choice: "A book" },
    cover0: { type: "noul", noul: 0.9 },
  },
};
let judgement: Promise<Judgement>;
let cover: Promise<{ medium: "book"; title: string }>;
let comments: Promise<unknown[]>;

// Bun module mocks survive mock.restore(). Preserve and restore their exports
// so later editor tests use the real judgement and storage implementations.
const dependencies = [
  "../../../utils/judgement-client",
  "../../../utils/flow-media",
  "../../../utils/system-one-budget",
  "../../../utils/idb",
  "../../../utils/anti-tabula-rasa",
  "../../../utils/user-comments",
  "../../../utils/bibliography",
  "../../../utils/house-store",
  "../../../utils/flow-diagnostics",
];
const savedModules = await Promise.all(
  dependencies.map(
    async (path) => [path, { ...(await import(path)) }] as const,
  ),
);

mock.module("../../../utils/judgement-client", () => ({
  askJudgement: () => {
    judgementCalls++;
    return judgement;
  },
}));
mock.module("../../../utils/flow-media", () => ({
  lookupWork: () => {
    coverCalls++;
    return cover;
  },
}));
mock.module("../../../utils/system-one-budget", () => ({
  systemOneWait: () => 0,
  spendSystemOne: () => {},
  backOffSystemOne: () => {},
}));
mock.module("../../../utils/idb", () => ({
  loadMetaFromIdb: async () => undefined,
  loadFoliosFromIdb: async () => [],
  loadFolioContentFromIdb: async () => "",
  saveMetaToIdb: async () => {},
  toStorable: (value: unknown) => value,
}));
mock.module("../../../utils/anti-tabula-rasa", () => ({
  DEFAULT_INTERVIEW_ANSWERS: {
    workingTitle: "",
    format: "",
    audience: "",
    goal: "",
    tone: "",
    constraints: "",
    successSignal: "",
  },
  htmlToPlainText: (html: string) => html,
}));
mock.module("../../../utils/user-comments", () => ({
  loadUserComments: () => comments,
}));
mock.module("../../../utils/bibliography", () => ({
  loadBibliographyForFolio: async () => [],
}));
mock.module("../../../utils/house-store", () => ({
  HOUSE_CHANGED_EVENT: "twyne:house-changed",
  loadHouseState: async () => emptyHouseState(),
}));
mock.module("../../../utils/flow-diagnostics", () => ({ logFlow: () => {} }));
const { startFlowConductor, flowSnapshot, flowController, FLOW_EVENT } =
  await import("./flow-conductor");

const cleanups: Array<() => void> = [];
beforeAll(() => {
  const dom = new JSDOM("<!doctype html><html><body></body></html>", {
    pretendToBeVisual: true,
  });
  for (const name of ["window", "document", "CustomEvent"] as const)
    Object.defineProperty(globalThis, name, {
      configurable: true,
      writable: true,
      value: name === "window" ? dom.window : dom.window[name],
    });
  Object.defineProperty(globalThis, "setInterval", {
    configurable: true,
    value: (callback: () => void) => {
      const id = ++nextInterval;
      ticks.set(id, callback);
      return id;
    },
  });
  Object.defineProperty(globalThis, "clearInterval", {
    configurable: true,
    value: (id: number) => ticks.delete(id),
  });
});
afterEach(() => {
  for (const cleanup of cleanups.splice(0).reverse()) cleanup();
  ticks.clear();
});
afterAll(() => {
  for (const [path, exports] of savedModules) mock.module(path, () => exports);
  for (const [name, descriptor] of originals) {
    if (descriptor) Object.defineProperty(globalThis, name, descriptor);
    else Reflect.deleteProperty(globalThis, name);
  }
  releaseGlobals();
});

function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}
async function flush() {
  for (let i = 0; i < 40; i++) await Promise.resolve();
}
function resetRequests() {
  judgementCalls = coverCalls = 0;
  judgement = Promise.resolve(answers);
  cover = Promise.resolve({ medium: "book", title: "The Odyssey" });
  comments = Promise.resolve([]);
}
function start(folioId: string) {
  const schema = new Schema({
    nodes: {
      doc: { content: "paragraph+" },
      paragraph: { content: "text*", group: "block" },
      text: { group: "inline" },
    },
    marks: { italic: {} },
  });
  const doc = schema.node("doc", null, [
    schema.node("paragraph", null, [
      schema.text("Reading "),
      schema.text("The Odyssey", [schema.mark("italic")]),
      schema.text(
        " sends me back to the long salt roads where traders weighed their loads and followed the coast before dawn.",
      ),
    ]),
  ]);
  const editor = {
    isDestroyed: false,
    state: EditorState.create({ doc, selection: TextSelection.create(doc, 1) }),
    on: () => {},
    off: () => {},
  } as unknown as Editor;
  const stop = startFlowConductor(editor, {
    folioId,
    brief: null,
    getClient: () => ({}) as ConvexClient,
  });
  cleanups.push(stop);
  const tick = ticks.get(nextInterval)!;
  return { stop, tick, editor };
}

test("a judgement finishing after teardown cannot resurrect the margin snapshot", async () => {
  resetRequests();
  const pending = deferred<Judgement>();
  judgement = pending.promise;
  const old = start("old-folio");
  await flush();
  expect(flowSnapshot().enabled).toBe(true);
  old.tick();
  await flush();
  expect(judgementCalls).toBe(1);
  old.stop();
  const closed = flowSnapshot();
  let publications = 0;
  const listener = () => {
    publications++;
  };
  window.addEventListener(FLOW_EVENT, listener);
  try {
    pending.resolve(answers);
    await flush();
    expect(flowSnapshot()).toBe(closed);
    expect(flowSnapshot().enabled).toBe(false);
    expect(flowController()).toBeNull();
    expect(coverCalls).toBe(0);
    expect(publications).toBe(0);
  } finally {
    window.removeEventListener(FLOW_EVENT, listener);
  }
});

test("the current conductor still publishes a completed cover lookup", async () => {
  resetRequests();
  const current = start("current-folio");
  await flush();
  current.tick();
  await flush();
  expect(coverCalls).toBe(1);
  expect(flowSnapshot().visible).toContainEqual(
    expect.objectContaining({
      id: "work:the odyssey",
      title: "The Odyssey",
      kind: "work",
    }),
  );
});

test("a cover lookup and old cleanup cannot overwrite the next folio", async () => {
  resetRequests();
  const pending = deferred<{ medium: "book"; title: string }>();
  cover = pending.promise;
  const old = start("old-folio");
  await flush();
  old.tick();
  await flush();
  expect(coverCalls).toBe(1);
  start("new-folio");
  await flush();
  const current = flowSnapshot();
  const currentController = flowController();
  old.stop();
  expect(flowSnapshot()).toBe(current);
  pending.resolve({ medium: "book", title: "Old folio's cover" });
  await flush();
  expect(flowSnapshot()).toBe(current);
  expect(flowController()).toBe(currentController);
  expect(currentController?.items()).toEqual([]);
  expect(current.enabled).toBe(true);
});

test("comments loaded after close cannot publish a stale conversation", async () => {
  resetRequests();
  const pending = deferred<unknown[]>();
  comments = pending.promise;
