    {
      id: "late-comment",
      folioId: "old-folio",
      text: "Old feedback",
      author: "Editor",
      anchor: "The Odyssey",
      resolved: false,
      replies: [],
      createdAt: Date.now(),
    },
  ]);
  await flush();
  expect(flowSnapshot()).toBe(closed);
  expect(flowSnapshot().visible).toEqual([]);
});

