/**
 * The galley slip: what one run of focused writing amounted to.
 *
 * The flow conductor opens a session when the page goes into flow and closes
 * it when flow ends, then announces the summary with `FLOW_SESSION_EVENT`.
 * The margin sets it as a small typed slip; the House keeps the recent ones.
 */

export const FLOW_SESSION_EVENT = "twyne:flow-session";

export type FlowSessionEnd =
  /** A long pause ended the run. */
  | "pause"
  /** The writer reached for the room (margin, masthead) or pressed Escape. */
  | "reached"
  /** The writer turned focus off by hand. */
  | "manual"
  /** No keys for a long while. */
  | "away"
  /** The editor closed or the folio changed mid-run. */
  | "closed";

export interface FlowSession {
  /** `${folioId}:${startedAt}` */
  id: string;
  folioId: string;
  /** When the page went into flow, ms since epoch. */
  startedAt: number;
  endedAt: number;
  /** Time spent in flow, ms. */
  flowMs: number;
  /** Net words set during the session (never negative). */
  words: number;
  /** Words a minute across the session. */
  wpm: number;
  /** Margin items that arrived, or were held back, while the page was quiet. */
  waited: number;
  /** Dossier amendments proposed during the session. */
  amendments: number;
  ended: FlowSessionEnd;
}
/**
 * The conductor — one place that decides what reaches the writer, and when.
 *
 * It reads the rhythm of the keys (`flow-state.ts`), fits that reading to
 * this writer (`flow-profile.ts`), gathers what the room, the Apparatus, the
 * shelf, the writer's other work, the charter and the dossier have to offer
 * (`flow-items.ts`), and lets through only what the moment allows:
 *
 *   in flow        the page stands alone; Twyne slips into focus by itself
 *   settling       the chrome dims; nothing new arrives
 *   working        a few margin cards, nearest the cursor first
 *   stuck          the single best thing for this paragraph
 *
 * Jev is asked only at the edges — whether a steady run really is composing,
 * whether a pause really is stuck, and which of the local candidates bear on
 * the paragraph — in one batched request per pause, under the shared System
 * One budget. Without Jev the local readings decide alone.
 *
 * Producers are not changed: this listens to the events they already fire.
 */
