    if (!active()) return;
    const previous = items.get(item.id);
    items.set(item.id, previous ? { ...previous, ...item } : item);
    if (!previous)
      logFlow("item", `${item.kind}: ${item.title}`, {
        anchors: item.anchors.map((a) => a.slice(0, 80)),
        relevance: item.relevance,
