  const setFocus = (on: boolean, why: string) => {
    if (on === autoFocus) return;
    autoFocus = on;
    logFlow("focus", on ? `Focus on: ${why}` : `Focus off: ${why}`);
    window.dispatchEvent(
      new CustomEvent("twyne:zen-mode", { detail: { on, source: "flow" } }),
    );
  };

  const onZen = (event: Event) => {
    if (!active()) return;
