  comment: 0.9,
  "persona-note": 0.75,
  charter: 0.7,
  amendment: 0.65,
  // Only offered while stuck, when it should lead.
  "way-in": 0.95,
  source: 0.55,
  echo: 0.55,
  work: 0.5,
  shelf: 0.45,
};

export interface WorkCard {
  medium: "book" | "album" | "song" | "film";
  title: string;
  creator?: string;
  year?: string;
  cover?: string;
  url?: string;
}

export interface FlowItem {
  id: string;
  kind: FlowItemKind;
  /** Passages in this manuscript the item speaks to, verbatim. */
