      data: last ? { reply: last.text, replyAuthor: last.author } : undefined,
      color: "var(--color-writer-note)",
    });
  }
  for (const id of [...items.keys()])
    if (id.startsWith("comment:") && !live.has(id)) items.delete(id);

item.stdout:
      if (id.startsWith("comment:") && !live.has(id)) items.delete(id);
