}

export const DEFAULT_THRESHOLDS: FlowThresholds = {
  gapMs: 4_000,
  settleMs: 30_000,
  flowMs: 90_000,
  stuckPauseMs: 18_000,
  exitPauseMs: 25_000,
  awayMs: 180_000,
  maxDeleteRatio: 0.3,
  minActiveRatio: 0.45,
