  assembleContextStack,
  collectionForFolio,
  contextForModels,
  DOSSIER_FIELD_LABELS,
  DOSSIER_FIELDS,
  emptyHouseState,
  INHERITABLE_FIELDS,
  LAYER_LABELS,
  LEDGER_SOURCE_LABELS,
  type CharterItem,
  type CharterScope,
  type ContextLayer,
