    const restoreDraft =
      prior?.mode === "compose" &&
      prior.from === range.from &&
      prior.to === range.to
        ? prior.draft
        : "";
    store.userCommentPopover = {
      mode: "compose",
      visible: true,
      id: "draft-margin",
      author: "You",
      text: "",
      quote,
      createdAt: Date.now(),
      x: geom.x,
      top: geom.top,
      bottom: geom.bottom,
      maxH: geom.maxH,
      from: range.from,
      to: range.to,
      resolved: false,
      replies: [],
      draft: restoreDraft,
    };
    store.selectionAction = null;
  },
);

const submitWriterMargin = $(async () => {
  const popover = store.userCommentPopover;
  if (
    !popover ||
    popover.mode !== "compose" ||
    popover.from == null ||
    popover.to == null ||
    !popover.draft.trim()
  ) {
    return;
  }
  await createSelectionComment(
    popover.draft.trim(),
    { from: popover.from, to: popover.to },
    true,
  );
});

