import type { NoSerialize, PropFunction, Signal } from "@qwik.dev/core";
import type { Editor } from "@tiptap/core";
import type {
  DocumentMeta,
  Folio,
  LayoutSettings,
  PersonaReply,
} from "../../types";
import type { UserCommentReply } from "../../utils/user-comments";
import type { ImageUploadAdapter } from "../../utils/image-upload";
import type { CompositorTab } from "../../utils/compositor-toolbar";
import type { DocumentOutlineModel } from "../../utils/document-outline";
import type { NoteKind } from "./extensions/endnote-node";
import type { ImageNodeAttributes } from "./extensions/image-node";
import type { SelectedCellFormat } from "./extensions/table-cell-format";
import type { TableToolbarSnapshot } from "./table-core";
import type { PanelId } from "../../utils/panel-activity";

/** A persona note anchored beside the passage it discusses. */
export interface NotePopover {
  id: string;
  author: string;
  color: string;
  label: string;
  note: string;
  x: number;
  top: number | null;
  bottom: number | null;
  maxH: number;
  placement: "above" | "below";
  quote?: string;
  briefTitle?: string;
  draft: string;
  dismissed: boolean;
  pinned: boolean;
  thread: PersonaReply[];
  replying: boolean;
  streamingReply: string;
  error: string | null;
  /** Flow item whose margin slot this card has unfolded into, if any. */
  margin?: string | null;
  /** Width of that slot; the card's own width otherwise. */
  width?: number;
}

/** A persona's proposed rewrite, presented for an explicit accept/strike decision. */
export interface SuggestionPopover {
  id: string;
  versionId: string;
  author: string;
  color: string;
  original: string;
  replacement: string;
  rationale: string;
  x: number;
  top: number | null;
  bottom: number | null;
  maxH: number;
  busy: boolean;
  /** Flow item whose margin slot this card has unfolded into, if any. */
  margin?: string | null;
  /** Width of that slot; the card's own width otherwise. */
  width?: number;
}

/** A note collected live from the document, in reading order and numbered per kind. */
export interface EditorNote {
  kind: NoteKind;
  number: number;
  text: string;
  pos: number;
}

/** A writer-authored inline comment and its reply thread. */
export interface UserCommentPopover {
  mode: "compose" | "thread";
  visible: boolean;
  id: string;
  author: string;
  text: string;
  quote: string;
  createdAt: number;
  x: number;
  top: number | null;
  bottom: number | null;
  maxH: number;
  from: number | null;
  to: number | null;
  resolved: boolean;
  replies: UserCommentReply[];
  draft: string;
  /** Flow item whose margin slot this card has unfolded into, if any. */
  margin?: string | null;
  /** Width of that slot; the card's own width otherwise. */
  width?: number;
}

/** The exact Tiptap selection owned by the manuscript action card. */
export interface SelectionActionState {
  from: number;
  to: number;
  text: string;
  /** Fixed viewport coordinates; the component centers itself on x. */
  x: number;
  y: number;

