const WRITER_SETTINGS_META_KEY = "writer-settings";
const APPARATUS_SETTINGS_META_KEY = "apparatus-settings";

export interface FolioContentSnapshot {
  folioId: string;
  html: string;
  format?: "html" | "typst";
  typstSource?: string;
  updatedAt: number;
}

interface BriefRecord {
  folioId: string;
